:"FullTextCatalog"}},{"cell_type":"markdown","source":["# [dbo].[SplitString]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/UserDefinedFunction[@Name='SplitString' and @Schema='dbo']","object_type":"UserDefinedFunction"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  UserDefinedFunction [dbo].[SplitString]    Script Date: 9/7/2025 5:45:27 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE FUNCTION [dbo].[SplitString]\r\n(\r\n    @Input NVARCHAR(MAX),\r\n    @Delimiter CHAR(1)\r\n)\r\nRETURNS @Output TABLE (Value NVARCHAR(MAX))\r\nAS\r\nBEGIN\r\n    DECLARE @Start INT, @End INT\r\n    SET @Start = 1\r\n\r\n    WHILE CHARINDEX(@Delimiter, @Input, @Start) > 0\r\n    BEGIN\r\n        SET @End = CHARINDEX(@Delimiter, @Input, @Start)\r\n        INSERT INTO @Output (Value) VALUES (SUBSTRING(@Input, @Start, @End - @Start))\r\n        SET @Start = @End + 1\r\n    END\r\n\r\n    INSERT INTO @Output (Value) VALUES (SUBSTRING(@Input, @Start, LEN(@Input) - @Start + 1))\r\n    RETURN\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/UserDefinedFunction[@Name='SplitString' and @Schema='dbo']","object_type":"UserDefinedFunction"}},{"cell_type":"markdown","source":["# [dbo].[Tbl_Agent]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/Table[@Name='Tbl_Agent' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Tbl_Agent]    Script Date: 9/7/2025 5:45:27 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Tbl_Agent](\r\n\t[ID] [int] IDENTITY(1,1) NOT NULL,\r\n\t[User_Id] [varchar](100) NOT NULL,\r\n\t[Agent_Name] [varchar](100) NOT NULL,\r\n\t[Agent_Organization_Name] [varchar](100) NOT NULL,\r\n\t[Agent_IC_Passport] [varchar](100) NOT NULL,\r\n\t[Agent_E