0250122-133511]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nCREATE UNIQUE NONCLUSTERED INDEX [NonClusteredIndex-20250122-133511] ON [dbo].[Tbl_Country]\r\n(\r\n\t[ID] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, IGNORE_DUP_KEY = OFF, DROP_EXISTING = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/Table[@Name='Tbl_Country' and @Schema='dbo']/Index[@Name='NonClusteredIndex-20250122-133511']","object_type":"Index"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_delete_menuid]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_delete_menuid' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_delete_menuid]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[Ads_delete_menuid] \r\n\t   @Role INT \r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n    -- Step 1: Delete the existing record for the given Role_ID and Menu_ID\n    DELETE FROM Tbl_Rights_Master\n    WHERE Role_ID = @Role;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_delete_menuid' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[ADS_Get_Dashboard_Count]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='ADS_Get_Dashboard_Count' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[ADS_Get_Dashboard_Count]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[ADS_Get_Dashboard_Count]\r\nAS\r\nBEGIN\r\n\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\nSELECT \n    COUNT(*) AS PassportExpiringWithin3Months\nFROM Tbl_Worker_PersonalInfo\nWHERE Passport_Expire_Date BETWEEN CAST(GETDATE() AS DATE) AND CAST(DATEADD(MONTH, 3, GETDATE()) AS DATE);\n\nSELECT \r\n    COUNT(*) AS ContractExpiryDateWithin3Months\r\nFROM Tbl_Worker_EmployerInfo\r\nWHERE Contract_Expiry_Date BETWEEN CAST(GETDATE() AS DATE) AND CAST(DATEADD(MONTH, 3, GETDATE()) AS DATE);\r\n\nSELECT \n    COUNT(*) AS PermitExpiringWithin3Months\nFROM Tbl_Worker_PermitInsurance\nWHERE Permit_Expire_Date BETWEEN CAST(GETDATE() AS DATE) AND CAST(DATEADD(MONTH, 3, GETDATE()) AS DATE);\n\nSELECT \n    COUNT(CASE WHEN Permit_Expire_Date = CAST(GETDATE() AS DATE) THEN 1 END) AS PermitExpiryDate\nFROM Tbl_Worker_PermitInsurance;\r\n\r\nSELECT \n    COUNT(*) AS PermitExpiringWithin30Days\nFROM Tbl_Worker_PermitInsurance\nWHERE Permit_Expire_Date BETWEEN CAST(GETDATE() AS DATE) AND CAST(GETDATE() + 30 AS DATE);\n\r\nSELECT COUNT(DISTINCT Prob_ID) AS prob_count\nFROM Tbl_ProbSol\nWHERE type = 'Problem';\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='ADS_Get_Dashboard_Count' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_Get_Edit_User_Access]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Edit_User_Access' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_Get_Edit_User_Access]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[Ads_Get_Edit_User_Access]\r\n\t@Role_ID [int]\r\nAS\r\nBEGIN\r\n\r\n\r\n    -- Insert statements for procedure here\r\n\tSELECT DISTINCT Role_Id, Menu_ID AS menuId, Status\nFROM Tbl_Rights_Master\nWHERE Role_Id = @Role_ID \nGROUP BY Role_Id, Menu_ID, Status;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Edit_User_Access' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_Get_Panic_List]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Panic_List' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_Get_Panic_List]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[Ads_Get_Panic_List]\r\n\t\r\nAS\r\nBEGIN\r\n\r\n\tSET NOCOUNT ON;\r\n\r\n    \r\nSelect DISTINCT Prob_ID as ProblemId,worker_ID AS WorkerId,title,description,Updated_On from Tbl_ProbSol\n    WHERE type = 'Problem';\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Panic_List' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_Get_Problem_Details_Worker_Details]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Problem_Details_Worker_Details' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_Get_Problem_Details_Worker_Details]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[Ads_Get_Problem_Details_Worker_Details]\r\n\t @Problem_Id varchar(50)\r\n\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\nselect Prob_Id,Type,Description,Title,Document,worker_ID,Updated_On from Tbl_ProbSol where Prob_Id=@Problem_Id\r\n\r\n\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Problem_Details_Worker_Details' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_Get_Problems_List]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Problems_List' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_Get_Problems_List]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE  [ADSFWWMCDB].[Ads_Get_Problems_List]\r\n\t\r\n\t\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n\tselect Prob_Id,Title,Description,ProbStatus from Tbl_ProbSol;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Problems_List' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_Get_User_Access_List]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_User_Access_List' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_Get_User_Access_List]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[Ads_Get_User_Access_List] \r\n\t\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n\tSELECT \n    rm.Role_ID, \n    MAX(rm.ID) AS ID,\n    R.Role_Name,\n\t'Employee' AS DepartmentName\nFROM \n    Tbl_Rights_Master rm\ninner JOIN \n    Tbl_Role R \n    ON rm.Role_ID = R.ID\nGROUP BY \n    rm.Role_ID, R.Role_Name;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_User_Access_List' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_Get_Worker_Details]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Worker_Details' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_Get_Worker_Details]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[Ads_Get_Worker_Details] \r\n  @Worker_Id varchar(50)\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\nSELECT \n    wp.Worker_Id as WorkerId,wp.Name,wp.Photo,wp.PhotoName,wp.Address,wp.Gender,ms.Marital_Status,t.City_Name,wp.Father_Name,wp.Mother_Name,wp.Passport_Number,wp.Passport_Issue_Date,wp.Passport_Expire_Date,\n\twi.Permit_Issue_Date,wi.Permit_Expire_Date,ei.Contract_issue_Date,\n\tei.Contract_Expiry_Date,tc.Country_Name,Contact_Number\nFROM Tbl_Worker_PersonalInfo wp\ninner join Tbl_Worker_PermitInsurance wi on wp.Worker_Id=wi.Worker_Id\ninner join Tbl_Worker_EmployerInfo ei on wp.Worker_Id=ei.Worker_Id\nleft join Tbl_MaritalStatus ms on wp.Marital_Status=ms.ID\nleft join Tbl_Country tc on wp.Nationality=tc.ID\nleft join Tbl_City t on wp.city=t.ID\nwhere wp.Worker_Id=@Worker_Id;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Worker_Details' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Ads_Worker_Details_Problem_Details]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Worker_Details_Problem_Details' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Ads_Worker_Details_Problem_Details]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[Ads_Worker_Details_Problem_Details]\r\n\t@Worker_Id varchar(50)\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n\tselect PI.Name,PI.Passport_Number,PI.Passport_Issue_Date,PI.Passport_Expire_Date,PI.Address,PI.Gender,PI.Date_Of_Birth,PI.Contact_Number,EI.Employer_Name,EI.Employer_Address,EI.Sector,EI.Sub_Sector,EI.Telephone_No,EI.Contact_Person,EI.Contact_Person_IC_NO,\nEI.Position,EI.Hp_Number,EI.Email,EI.Contract_Expiry_Date,EI.Contract_issue_Date,EI.Created_By \n,ms.Marital_Status,tc.Country_Name\nfrom Tbl_Worker_PersonalInfo PI\nINNER JOIN Tbl_Worker_EmployerInfo EI \nON EI.Worker_Id=PI.Worker_Id\nleft join Tbl_MaritalStatus ms on PI.Marital_Status=ms.ID\nleft join Tbl_Country tc on PI.Nationality=tc.ID\n WHERE EI.Worker_Id=@Worker_Id;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Worker_Details_Problem_Details' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[Get_Dashboard_Expiry_Details_Page]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Get_Dashboard_Expiry_Details_Page' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[Get_Dashboard_Expiry_Details_Page]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [ADSFWWMCDB].[Get_Dashboard_Expiry_Details_Page] \r\n    @Flag INT -- Add the Flag parameter (1 or 0 or 2)\r\nAS\r\nBEGIN\r\n    -- SET NOCOUNT ON added to prevent extra result sets from\r\n    -- interfering with SELECT statements.\r\n    SET NOCOUNT ON;\r\n\r\n    -- If the flag is 1, apply the condition for Passport Expiry within 3 months\r\n    IF @Flag = 1\r\n    BEGIN\r\n        -- Select details for workers whose passport expires within the next 3 months\r\n        SELECT \r\n            wp.Worker_Id AS WorkerId,\r\n            wp.Name,\r\n            wp.Photo,\r\n\t\t\twp.PhotoName,\r\n            wp.Passport_Number,\r\n            wp.Passport_Issue_Date,\r\n            wp.Passport_Expire_Date,\r\n            wi.Permit_Issue_Date,\r\n            wi.Permit_Expire_Date,\r\n            ei.Contract_issue_Date,\r\n            ei.Contract_Expiry_Date,\r\n            wp.Nationality,\r\n\t\t\ttc.Country_Name,\r\n            wp.Contact_Number\r\n        FROM Tbl_Worker_PersonalInfo wp\r\n        INNER JOIN Tbl_Worker_PermitInsurance wi ON wp.Worker_Id = wi.Worker_Id\r\n        INNER JOIN Tbl_Worker_EmployerInfo ei ON wp.Worker_Id = ei.Worker_Id\r\n\t\tLEFT JOIN Tbl_Country tc ON wp.Nationality = tc.ID\r\n        WHERE wp.Passport_Expire_Date BETWEEN CAST(GETDATE() AS DATE) AND CAST(DATEADD(MONTH, 3, GETDATE()) AS DATE);\r\n    END\r\n    -- If the flag is 2, apply the condition for Permit Expiry within 3 months\r\n    ELSE IF @Flag = 2\r\n    BEGIN\r\n        -- Select details for workers whose permit expires within the next 3 months\r\n        SELECT \r\n            wp.Worker_Id AS WorkerId,\r\n            wp.Name,\r\n            wp.Photo,\r\n\t\t\twp.PhotoName,\r\n            wp.Passport_Number,\r\n            wp.Passport_Issue_Date,\r\n            wp.Passport_Expire_Date,\r\n            wi.Permit_Issue_Date,\r\n            wi.Permit_Expire_Date,\r\n            ei.Contract_issue_Date,\r\n            ei.Contract_Expiry_Date,\r\n            wp.Nationality,\r\n\t\t\ttc.Country_Name,\r\n            tc.Country_Name,\r\n            wp.Contact_Number\r\n        FROM Tbl_Worker_PermitInsurance pi\r\n        INNER JOIN Tbl_Worker_PersonalInfo wp ON pi.Worker_Id = wp.Worker_Id\r\n        INNER JOIN Tbl_Worker_PermitInsurance wi ON pi.Worker_Id = wi.Worker_Id\r\n        INNER JOIN Tbl_Worker_EmployerInfo ei ON pi.Worker_Id = ei.Worker_Id\r\n        LEFT JOIN Tbl_Country tc ON wp.Nationality = tc.ID\r\n        WHERE pi.Permit_Expire_Date BETWEEN CAST(GETDATE() AS DATE) AND CAST(DATEADD(MONTH, 3, GETDATE()) AS DATE);\r\n    END\r\n\tELSE IF @Flag = 3\r\n    BEGIN\r\n\t      SELECT \r\n     wp.Worker_Id as WorkerId,wp.Name,wp.Photo,wp.PhotoName,wp.Passport_Number,wp.Passport_Issue_Date,wp.Passport_Expire_Date,wi.Permit_Issue_Date,wi.Permit_Expire_Date,ei.Contract_issue_Date,ei.Contract_Expiry_Date,Nationality,tc.country_name,Contact_Number\r\nFROM Tbl_Worker_EmployerInfo ei\r\ninner join Tbl_Worker_PersonalInfo wp on ei.Worker_Id=wp.Worker_Id\r\ninner join Tbl_Worker_PermitInsurance wi on ei.Worker_Id=wi.Worker_Id\r\nleft join Tbl_Country tc on wp.Nationality=tc.ID\r\nWHERE Contract_Expiry_Date BETWEEN CAST(GETDATE() AS DATE) AND CAST(DATEADD(MONTH, 3, GETDATE()) AS DATE);\n\r\n\tEND\r\n    -- You can add more conditions for other values of @Flag if needed\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Get_Dashboard_Expiry_Details_Page' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[GetUserMenu]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='GetUserMenu' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[GetUserMenu]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[GetUserMenu] \r\n\t @UserId NVARCHAR(100)\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n\t\r\nselect distinct d.User_ID,d.User_Name, d.User_Status as 'UserStatus',d.User_Role,a.Menu_ID,a.ISDefault,a.Status,b.PAGE_NAME,b.PAGE_URL,--b.IMAGE,\r\nc.Role_Status as RoleStatus,b.parent_id  from\r\nTbl_Rights_Master a,Tbl_Menu_Details b,TBL_ROLE c,tbl_user d\r\nwhere a.Menu_ID=b.ID and a.Role_ID=c.ID and d.User_Role=a.Role_ID\r\nand d.User_Id=@UserId\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='GetUserMenu' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[GetUserMenuNew]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='GetUserMenuNew' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[GetUserMenuNew]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCreate PROCEDURE [ADSFWWMCDB].[GetUserMenuNew] \r\n\t @UserId NVARCHAR(100),\r\n\t@RoleId INT = NULL\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n\t\r\nselect distinct(rt.ROLE_ID),User_Id,User_Status,Parent_ID,PAGE_NAME,PAGE_URL,\r\nrt.Menu_id,rt.Role_ID,rt.Status,rt.ISDefault from Tbl_Rights_Master rt\r\ninner join Tbl_Menu_Details md on rt.Menu_Id=md.ID\r\ninner join tbl_user tu on tu.user_role=rt.Role_ID \r\nwhere rt.Role_ID=@RoleId and User_Id=@UserId\r\n\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='GetUserMenuNew' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[InsertUserMenuAccess]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUserMenuAccess' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[InsertUserMenuAccess]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\n-- Author:\t\t<Author,,Name>\n-- Create date: <Create Date,,>\n-- Description:\tDelete specific record by Role_ID and Menu_ID, then insert new record.\n-- =============================================\nCREATE PROCEDURE [ADSFWWMCDB].[InsertUserMenuAccess]\n    @Role INT,               -- Role ID\n    @Menu_ID INT,            -- Single Menu ID to insert\n    @Status INT,             -- Status (1 for selected, 0 for not selected)\n    @Userid VARCHAR(100)     -- User ID for tracking\nAS\nBEGIN\n    -- Declare a variable to store the message\n    DECLARE @Message NVARCHAR(255);\n\n    -- Step 1: Delete the existing record for the given Role_ID and Menu_ID\n    DELETE FROM Tbl_Rights_Master\n    WHERE Role_ID = @Role AND Menu_ID = @Menu_ID;\n\n    -- Step 2: Insert a new record for the provided Menu_ID and Status\n    INSERT INTO Tbl_Rights_Master (Role_ID, Menu_ID, Status, ISDefault, UpdatedBy, UpdatedOn)\n    VALUES (@Role, @Menu_ID, @Status, 0, @Userid, GETDATE());\n\n    -- Set the success message\n    SET @Message = 'User permission successfully added ';\n\n    -- Return the message to the caller\n    SELECT @Message AS Message;\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUserMenuAccess' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[sp_GetEmployerReport]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_GetEmployerReport' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[sp_GetEmployerReport]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [ADSFWWMCDB].[sp_GetEmployerReport]\r\nAS\r\nBEGIN\r\n    -- created by nandkishor 21-01-2025\r\n    select *,STUFF(\r\n        (\r\n            SELECT ', ' + c.Country_Name\r\n            FROM dbo.SplitString(e.Employer_FWC, ',') s\r\n            INNER JOIN Tbl_Country c\r\n                ON c.ID = s.Value\r\n            FOR XML PATH(''), TYPE\r\n        ).value('.', 'NVARCHAR(MAX)'), \r\n        1, 2, ''\r\n    ) AS CountryNames from tbl_employer e left join  tbl_sector s on e.employer_sector=s.id left join tbl_subsector ss on e.employer_subsector=ss.id  --left join tbl_country c on e.employer_FWC =c.id\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_GetEmployerReport' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[sp_Insert_ProbSol]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_Insert_ProbSol' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[sp_Insert_ProbSol]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- Author:\t\tNandkishor\r\n-- Create date: 29.01.2025\r\n-- Description:\tTo Insert Problem / solution Data\r\n-- =============================================\r\nCREATE PROCEDURE [ADSFWWMCDB].[sp_Insert_ProbSol]\r\n    @Prob_ID VARCHAR(50) = NULL,\r\n    @Title VARCHAR(200) = NULL ,\r\n    @Description VARCHAR(500),\r\n    @Updated_By VARCHAR(50) = NULL,\r\n    @Updated_On DATETIME = NULL,\r\n    @Document VARBINARY(MAX) = NULL, -- For binary document storage\r\n    @ActionType VARCHAR(20), -- 'Problem' or 'Solution'\r\n\t@worker_ID VARCHAR(20)=NULL\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    IF @ActionType = 'Problem'\r\n    BEGIN\r\n        -- Insert a new problem\r\n        INSERT INTO Tbl_ProbSol (Prob_ID, Title, Type, Description, ProbStatus, Updated_By, Updated_On, Document,WORKER_id)\r\n        VALUES (@Prob_ID, @Title, 'PROBLEM', @Description, 'Open', @Updated_By, GETDATE(), @Document,@worker_ID);\r\n\r\n\t\t-- Retrieve the identity value\r\n            DECLARE @NewId INT = SCOPE_IDENTITY();\r\n\r\n        \r\n            DECLARE @Problem_ID NVARCHAR(100) = 'PROB' + RIGHT('00000' + CAST(@NewId AS NVARCHAR), 4);\r\n\r\n            -- Update the record with the generated UserId\r\n            UPDATE Tbl_ProbSol\r\n            SET prob_id = @Problem_ID\r\n            WHERE Id = @NewId;\r\n    END\r\n    ELSE IF @ActionType = 'Solution'\r\n    BEGIN\r\n        -- Insert a new solution\r\n        INSERT INTO Tbl_ProbSol (Prob_ID, Type, Description, ProbStatus, Updated_By, Updated_On,WORKER_id)\r\n        VALUES (@Prob_ID, 'SOLUTION', @Description, 'WIP', @Updated_By, GETDATE(),@worker_ID);\r\n    END\r\n    ELSE\r\n    BEGIN\r\n        -- Return error message for invalid ActionType\r\n        PRINT 'Invalid ActionType. Use \"Problem\" or \"Solution\".';\r\n    END\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_Insert_ProbSol' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADSFWWMCDB].[sp_Reports]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_Reports' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [ADSFWWMCDB].[sp_Reports]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [ADSFWWMCDB].[sp_Reports]\r\n    @Action NVARCHAR(50) \r\nAS\r\nBEGIN\r\n    -- Created by Nandkishor 22/01/2025\r\n\r\n    IF @Action = 'employerReport'\r\n    BEGIN\r\n        -- Fetch Employer Report\r\n       select *,STUFF(\r\n        (\r\n            SELECT ', ' + c.Country_Name\r\n            FROM dbo.SplitString(e.Employer_FWC, ',') s\r\n            INNER JOIN Tbl_Country c\r\n                ON c.ID = s.Value\r\n            FOR XML PATH(''), TYPE\r\n        ).value('.', 'NVARCHAR(MAX)'), \r\n        1, 2, ''\r\n    ) AS CountryNames from tbl_employer e left join  tbl_sector s on e.employer_sector=s.id left join tbl_subsector ss on e.employer_subsector=ss.id  --left join tbl_country c on e.employer_FWC =c.id\r\n    END\r\n\tELSE IF @Action = 'UserReport'\r\n\tBEGIN\r\n\t\t\tSELECT u.ID, u.User_Name, u.Email_ID, u.User_Status, u.User_Role, u.User_Title, u.User_Branch,\r\n\t\t\t   s.Status, r.Role_Name, t.Title_Name, b.Branch_Name\r\n\t\tFROM tbl_User u\r\n\t\tLEFT JOIN tbl_Status s ON u.User_Status = s.ID\r\n\t\tLEFT JOIN tbl_Role r ON u.User_Role = r.ID\r\n\t\tLEFT JOIN tbl_Title t ON u.User_Title = t.ID\r\n\t\tLEFT JOIN tbl_Branch b ON u.User_Branch = b.ID\r\n\t\tORDER BY u.ID DESC\r\n\tEND\r\n    ELSE IF @Action = 'agentReport'\r\n\tBEGIN\r\n\t\t\tselect agent_name,agent_organization_name,agent_ic_passport,agent_emailid,d.department_name,c.country_name,agent_contactnumber,a.created_by,a.created_on\r\n\t\t   from tbl_agent a \r\n\t\t   left join tbl_department d on a.agent_department = d.id \r\n\t\t   left join tbl_country c on a.agent_country= c.id\r\n\tEND\r\n\r\n\tELSE IF @Action = 'WorkerReport'\r\n\tBEGIN\r\n\t\t\tselect wpi.Worker_Id, Name, Passport_Number, Passport_Issue_Date, Passport_Expire_Date, Address, District, city_name, country_name, state_name, Gender, Date_Of_Birth, Contact_Number, ms.Marital_Status, Highest_Education, Email_Id, Mother_Name, Father_Name, Branch_Name,  wpi.Created_By, wpi.Created_On,\r\n Permit_Issue_Date, Permit_Expire_Date, Permit_Issue_Place, Insurance_Policy_Number, Source_Country_Insurance, Malaysia_Insurance, SOSCO_Number, Relationship_Two, Spouse_Name, Legal_Beneficiary_Two, Contact_Number_of_Spouse, Contact_Number_Two, Legal_Beneficiary_One, Contact_Number_One, Relationship_One,\r\n  Malaysian_Reqruitment_Agency, Source_Country_Requirtment_Agency, License_No_M, License_NO_S, Address_M, Address_S, Email_Address_M, Email_Address_S, Contact_Person_M, Contact_Person_S, Contact_Number_M, Contact_Number_S, Website_M, Website_S,\r\n SOC_ROC_ROC_No, Employer_Name, Employer_Address, Sector_Name, SubSector_name, Telephone_No, Contact_Person, Contact_Person_IC_No, Position, Hp_Number, Email, Contract_Expiry_Date, Contract_issue_Date, Employment_Description\r\n  from [dbo].[Tbl_Worker_PersonalInfo] wpi \r\n  left join   [dbo].[Tbl_Worker_PermitInsurance] PI on wpi.Worker_id=pi.Worker_id \r\n  left join [dbo].[Tbl_Worker_RecruitAgent] ra on wpi.Worker_id=ra.Worker_id \r\n  left join [dbo].[Tbl_Worker_EmployerInfo] EI on  wpi.Worker_id=EI.Worker_id\r\n  left join tbl_country c on wpi.city=c.id\r\n  left join tbl_city ct on wpi.city=ct.id\r\n  left join tbl_state st on wpi.city=st.id\r\n  left join tbl_maritalstatus ms on wpi.Marital_Status=ms.id\r\n  left join tbl_branch b on wpi.Branch=b.id\r\n  left join tbl_sector s on EI.Sector=s.id\r\n  left join tbl_subsector ss on EI.sub_Sector=ss.id\r\n\r\n\tEND\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_Reports' and @Schema='ADSFWWMCDB']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[AddWorker]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='AddWorker' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[AddWorker]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[AddWorker] \r\n\t--\"Personal Information\"\r\n         @Name varchar(100) =null,--NOT NULL\r\n\r\n        @Passport_Number varchar(20)=null,--NOT NULL\r\n\r\n        @Passport_Issue_Date Datetime2=NULL,\r\n\r\n        @Passport_Expiry_Date Datetime2=Null,--NOT NULL\r\n\r\n        @Address varchar(250)=null,--NOT NULL\r\n\r\n        @District varchar(50)=NULL,\r\n\r\n        @City  int =NULL,\r\n\r\n        @Nationality int=null,--NOT NULL\r\n\r\n\r\n        @State int=NULL,\r\n\r\n        @Gender varchar(10)=NULL,\r\n\r\n        @DOB Datetime2=null,--NOT NULL\r\n\r\n        @ContactNumber varchar(20)=NULL,\r\n\r\n        @Marital_Status int=NULL,\r\n\r\n        @Highest_Education varchar(20)=NULL,\r\n\r\n        @Email_Id varchar(250)=NULL,\r\n\r\n        @Mother_Name varchar(20)=NULL,\r\n\r\n        @Father_Name varchar(20)=NULL,\r\n\r\n       @Branch int=NULL,\r\n\r\n\t   @photoname varchar(50)=null,\r\n\r\n        @photo varchar(MAX)=NULL,\r\n\r\n\t\t@Employer_Id varchar(20)=null,\r\n        \r\n\r\n\r\n        --#region Permit Status And Insurance\r\n\r\n        @Permit_Issue_Date Datetime2=NULL,\r\n\r\n        @Permit_Expire_Date Datetime2=Null,--NOT NULL\r\n\r\n        @Permit_Issue_Place varchar(20)=NULL,\r\n\r\n        @Insurance_Policy_No varchar(20)=NULL,\r\n\r\n        @Source_Country_Insurance varchar(20)=NULL,\r\n\r\n        @Malaysia_Insurance varchar(20)=NULL,\r\n\r\n        @SOSCO_Number varchar(20)=NULL,\r\n\r\n        @Relationshiptwo varchar(20)=NULL,\r\n\r\n        @Spouse_Name varchar(20)=NULL,\r\n\r\n        @Legalbeneficiarytwo varchar(20)=NULL,\r\n\r\n        @Contact_Number_Spouse varchar(20)=NULL,\r\n\r\n        @Contact_Number_Two varchar(20)=NULL,\r\n\r\n        @Legal_Beneficiary_One varchar(20)=NULL,\r\n\r\n        @Contact_No_One varchar(20)=NULL,\r\n\r\n        @Relationship_One varchar(20)=NULL,\r\n        \r\n\r\n--# region \"Employer Information\"\r\n\r\n        @SOC_ROC_ROC_No varchar(50)=NULL,\r\n\r\n        @Employer_Name varchar(50)=NULL,\r\n\r\n        @Employer_Address varchar(100) =NULL,\r\n\r\n        @Sector int=NULL,\r\n\r\n        @Sub_Sector int=NULL,\r\n\r\n        @Telephone_No varchar(20)=NULL,\r\n\r\n        @Contact_Person varchar(20)=NULL,\r\n\r\n        @Contact_Person_IC_No varchar(20)=NULL,\r\n\r\n        @Position varchar(20)=NULL,\r\n\r\n        @hp_Number varchar(50)=NULL,\r\n\r\n        @Email varchar(50)=NULL,\r\n\r\n        @Contract_Expiry_Date Datetime2=NULL,\r\n\r\n        @Contract_issue_Date Datetime2=NULL,\r\n\r\n        @Employment_Description varchar(500)=NULL,\r\n        \r\n\r\n--# region Reqruitment Agents\r\n\r\n        @Malaysian_Reqruitment_Agency varchar(50)=NULL,\r\n\r\n        @Source_Country_Requirtment_Agency varchar(50)=NULL,\r\n\r\n        @License_No_M varchar(50)=NULL,\r\n\r\n        @Licenrse_NO_S varchar(50)=NULL,\r\n\r\n        @Address_M varchar(50)=NULL,\r\n\r\n        @Address_S varchar(50)=NULL,\r\n\r\n        @Email_Address_M varchar(250)=NULL,\r\n\r\n        @Email_Address_S varchar(250)=NULL,\r\n\r\n        @Contact_Person_M varchar(20)=NULL,\r\n\r\n        @Contact_Person_S varchar(20)=NULL,\r\n\r\n        @Contact_Number_M varchar(20)=NULL,\r\n\r\n        @Contact_Number_S varchar(20)=NULL,\r\n\r\n        @Website_M varchar(250)=NULL,\r\n\r\n        @Website_S varchar(250)=NULL,\r\n        \r\n\r\n--# region Attachment\r\n       @Passportcopyfilename varchar(50)=null,\r\n        @Passport_Copy varchar(MAX)=NULL,\r\n\t\t@Permitcopyfilename varchar(50)=null,\r\n         @Permit_Copy varchar(MAX)=NULL,\r\n\t\t @demandletterfilename varchar(50)=null,\r\n        @Demand_Letter varchar(MAX)=NULL,\r\n\t\t@Employmentcontractfilename varchar(50)=null,\r\n        @Employment_Contract varchar(MAX)=NULL,\r\n\t\t@Insurancepolicyfilename varchar(50)=null,\r\n        @Insurance_Policy varchar(MAX)=NULL,\r\n\r\n\t\t@Worker_Id varchar(100) OUTPUT,\r\n\r\n\t\t@action varchar(50)=Null,\r\n\r\n\t\t@generated_workerid varchar(100)=null,\r\n\r\n\t\t@filepath varchar(MAX)=null,\r\n\r\n\t\t@filetype varchar(50)=null,\r\n\r\n\t\t@fileName varchar(100)=null,\r\n\r\n\t\t@Created_By varchar(50)=null,\r\n\r\n\t\t@id int=null,\r\n\t\t@EmpId varchar(50)=null,\r\n\r\n\t\t@WorkerId1 varchar(20) =null,\r\n\r\n\t\t@Branch_Name varchar(20) =null,\r\n\r\n\t\t@State_Name varchar(50) =null,\r\n\r\n\t\t@City_Name varchar(50) =null,\r\n\r\n\t\t@subvalue varchar(20) =null,\r\n\r\n\t\t@SubName varchar(50)=null,\r\n\r\n\t\t@Contact_Number_Country_Code varchar(10)=null,\r\n\r\n\t\t@Spouse_Contact_No_CC varchar(10)=null,\r\n\r\n\t\t@Contact_No_Two_CC varchar(10)=null,\r\n\r\n\t\t@Contact_No_One_CC varchar(10)=null,\r\n\r\n\t\t@Contact_No_S_CC varchar(10)=null,\r\n\r\n\t\t@Contact_N0_M_CC varchar(10)=null,\r\n\r\n\t\t@TelephonenoCC varchar(10)=null\r\n\t\t\r\n\r\n\t\t\r\n--#region Attachments\r\n\r\n        \r\n\r\nAS\r\nBEGIN\r\nDECLARE @WorkerId VARCHAR(50);\r\nDECLARE @VALUE INT;\r\n    \r\nif(@action='GENERATE_ID')\r\nBegin\r\n\r\n\r\n\r\n\r\n\t -- Insert into Personal Information table\r\n    Insert into[Tbl_Worker_PersonalInfo]([Worker_Id],[Name], [Passport_Number], [Passport_Issue_Date], [Passport_Expire_Date],\n            [Address], [District], [City], [Nationality], [State], [Gender], [Date_of_Birth],\n            [Contact_Number], [Marital_Status], [Highest_Education], [Email_Id], [Mother_Name],\n            [Father_Name], [Branch], [Photo],[Photoname],[Created_By],[Created_On],[Employer_Id],[Contact_Number_Country_Code])\r\n\tValues('work000',@Name, @Passport_Number, @Passport_Issue_Date, @Passport_Expiry_Date,\n            @Address, @District, @City, @Nationality, @State, @Gender, @DOB, \n            @ContactNumber, @Marital_Status, @Highest_Education, @Email_Id, @Mother_Name,\n            @Father_Name, @Branch, @photo,@photoname,@Created_By,getdate(),@Employer_Id,@Contact_Number_Country_Code);\r\n\r\n\t\t\t-- Get the WorkerId from the inserted record\r\n\r\n\t\t\t Set @VALUE = SCOPE_IDENTITY();\r\n  IF (@VALUE IS NOT NULL)\n    BEGIN\n        -- Concatenate 'Work000' with @VALUE and assign to @WorkerId\n        SET @WorkerId = 'WKR000' + CAST(@VALUE AS VARCHAR);\n\n\t\tSET @Worker_Id =@WorkerId;\n        \n        -- Print the result to check\n        PRINT @Worker_Id;\n    END\n    ELSE\n    BEGIN\n        PRINT 'SCOPE_IDENTITY() returned NULL';\n    END\r\n\tupdate [Tbl_Worker_PersonalInfo] set [Worker_Id]=@WorkerId where [Worker_Id]='work000';\r\n\r\n\r\n\t -- Insert into Permit_Status_Insurance table\r\n  Insert into[Tbl_Worker_PermitInsurance]([Worker_id],[Permit_Issue_Date], [Permit_Expire_Date], \n            [Permit_Issue_Place], [Insurance_Policy_Number], [Source_Country_Insurance], \n            [Malaysia_Insurance], [SOSCO_Number], [Relationship_Two], [Spouse_Name], \n            [Legal_Beneficiary_Two], [Contact_Number_of_Spouse], [Contact_Number_Two], [Legal_Beneficiary_One],\n            [Contact_Number_one], [Relationship_One],[Created_By],[Created_On],[Spouse_Contact_No_CC],[Contact_No_Two_CC],[Contact_No_One_CC])\r\n\r\n     Values(@WorkerId,@Permit_Issue_Date, @Permit_Expire_Date, \n            @Permit_Issue_Place, @Insurance_Policy_No, @Source_Country_Insurance, \n            @Malaysia_Insurance, @SOSCO_Number, @Relationshiptwo, @Spouse_Name, \n            @Legalbeneficiarytwo, @Contact_Number_Spouse, @Contact_Number_Two, \n            @Legal_Beneficiary_One, @Contact_No_One, @Relationship_One,@Created_By,getdate(),@Spouse_Contact_No_CC,@Contact_No_Two_CC,@Contact_No_One_CC)\r\n\r\n\t-- Insert into EmployerInformation table\r\n  Insert into[Tbl_Worker_EmployerInfo]([Worker_Id], [SOC_ROC_ROC_No], [Employer_Name], [Employer_Address],\n            [Sector], [Sub_Sector], [Telephone_No], [Contact_Person], [Contact_Person_IC_NO],\n            [Position], [HP_Number], [Email], [Contract_Expiry_Date], [Contract_Issue_Date], \n            [Employment_Description],[Created_By],[Created_On],[TelephonenoCC])\r\n\r\n    values(@WorkerId,@SOC_ROC_ROC_No, @Employer_Name, @Employer_Address, @Sector, @Sub_Sector, \n            @Telephone_No, @Contact_Person, @Contact_Person_IC_No, @Position, \n            @hp_Number, @Email, @Contract_Expiry_Date, @Contract_issue_Date, \n            @Employment_Description,@Created_By,getdate(),@TelephonenoCC)\r\n     \r\n\t -- Insert into Recruitment_Agents table\r\n\tInsert into[Tbl_Worker_RecruitAgent]([Worker_Id],[Malaysian_Reqruitment_Agency], [Source_Country_Requirtment_Agency],\n            [License_No_M], [License_No_S], [Address_M], [Address_S], [Email_Address_M], \n            [Email_Address_S], [Contact_Person_M], [Contact_Person_S], [Contact_Number_M], \n            [Contact_Number_S], [Website_M], [Website_S],[Created_By],[Created_On],[Contact_No_S_CC],[Contact_N0_M_CC])\r\n\tvalues (@WorkerId,@Malaysian_Reqruitment_Agency, \n            @Source_Country_Requirtment_Agency, @License_No_M, @Licenrse_NO_S, \n            @Address_M, @Address_S, @Email_Address_M, @Email_Address_S, \n            @Contact_Person_M, @Contact_Person_S, @Contact_Number_M, \n            @Contact_Number_S, @Website_M, @Website_S,@Created_By,getdate(),@Contact_No_S_CC,@Contact_N0_M_CC)\r\n\r\n        -- Insert into Attachments table\r\n\tInsert into [Tbl_Worker_Attachments]([Worker_Id],[Passport_Copy_Filename], [Passport_Copy],[Permit_Copy_Filename], [Permit_Copy], \n            [Demand_Letter_Filename],[Demand_Letter],[Employment_Contract_Filename], [Employment_Contract],[Insurance_Policy_Filename], [Insurance_Policy],[Created_By],[Created_On])\r\n\tValues(@WorkerId,@Passportcopyfilename,@Passport_Copy,@Permitcopyfilename, @Permit_Copy, \n            @demandletterfilename,@Demand_Letter,@Employmentcontractfilename, @Employment_Contract,@Insurancepolicyfilename, @Insurance_Policy,@Created_By,getdate())\r\n\tEND\r\nelse IF (@action = 'UPDATE_FILEPATH')\r\nBEGIN\r\n    IF (@filetype = 'photo')\r\n    BEGIN\r\n        UPDATE [Tbl_Worker_PersonalInfo]\r\n        SET Photo = @filepath, PhotoName = @fileName\r\n        WHERE Worker_Id = @generated_workerid;\r\n    END\r\n\telse if(@filetype ='Passport_copy')\r\n\tBEGIN\r\n\tupdate [Tbl_Worker_Attachments] set Passport_Copy=@filepath ,Passport_Copy_Filename=@fileName where Worker_Id=@generated_workerid;\r\n\tEND\r\n\r\n\telse if(@filetype ='Permit_Copy')\r\n\tBEGIN\r\n\tupdate [Tbl_Worker_Attachments] set Permit_Copy=@filepath ,Permit_Copy_Filename=@fileName where Worker_Id=@generated_workerid;\r\n\tEND\r\n\r\n\telse if(@filetype ='Demand_Letter')\r\n\tBEGIN\r\n\tupdate [Tbl_Worker_Attachments] set Demand_Letter=@filepath ,Demand_Letter_Filename=@fileName where Worker_Id=@generated_workerid;\r\n\tEND\r\n\r\n\r\n    else if(@filetype ='Employment_Contract')\r\n\tBEGIN\r\n\tupdate [Tbl_Worker_Attachments] set Employment_Contract=@filepath ,Employment_Contract_Filename=@fileName where Worker_Id=@generated_workerid;\r\n\tEND\r\n\r\n\telse if(@filetype ='Insurance_Policy')\r\n\tBEGIN\r\n\tupdate [Tbl_Worker_Attachments] set Insurance_Policy=@filepath ,Insurance_Policy_Filename=@fileName where Worker_Id=@generated_workerid;\r\n\tEND\r\n\t\r\n\r\nEND\r\nelse if(@action ='GetData')\r\nBegin\r\n  select * from [dbo].[Tbl_Worker_PersonalInfo] order by 1 desc\r\n  select * from [dbo].[Tbl_Worker_PermitInsurance] order by 1 desc\r\n  select * from [dbo].[Tbl_Worker_EmployerInfo] order by 1 desc\r\n  select * from [dbo].[Tbl_Worker_RecruitAgent] order by 1 desc\r\n  select * From [dbo].[Tbl_Worker_Attachments] order by 1 desc\r\n  \r\nEND\r\n\r\nelse if(@action ='Update')\r\nBegin\r\n       UPDATE [Tbl_Worker_PersonalInfo]\r\nSET \r\n    [Name] = @Name,\r\n    [Passport_Number] = @Passport_Number,\r\n    [Passport_Issue_Date] = @Passport_Issue_Date,\r\n    [Passport_Expire_Date] = @Passport_Expiry_Date,\r\n    [Address] = @Address,\r\n    [District] = @District,\r\n    [City] = @City,\r\n    [Nationality] = @Nationality,\r\n    [State] = @State,\r\n    [Gender] = @Gender,\r\n    [Date_of_Birth] = @DOB,\r\n    [Contact_Number] = @ContactNumber,\r\n    [Marital_Status] = @Marital_Status,\r\n    [Highest_Education] = @Highest_Education,\r\n    [Email_Id] = @Email_Id,\r\n    [Mother_Name] = @Mother_Name,\r\n    [Father_Name] = @Father_Name,\r\n    [Branch] = @Branch,\r\n    --[Photo] = @photo,\r\n    --[Photoname] = @photoname,\r\n    [Created_By] = @Created_By,\r\n    [Created_On] = GETDATE(),\r\n\t[Contact_Number_Country_Code]=@Contact_Number_Country_Code\r\nWHERE \r\n    [Worker_Id] = @WorkerId1;\r\n\r\n\r\n\r\n\r\n\tUPDATE [Tbl_Worker_PermitInsurance]\r\nSET \r\n    [Permit_Issue_Date] = @Permit_Issue_Date,\r\n    [Permit_Expire_Date] = @Permit_Expire_Date,\r\n    [Permit_Issue_Place] = @Permit_Issue_Place,\r\n    [Insurance_Policy_Number] = @Insurance_Policy_No,\r\n    [Source_Country_Insurance] = @Source_Country_Insurance,\r\n    [Malaysia_Insurance] = @Malaysia_Insurance,\r\n    [SOSCO_Number] = @SOSCO_Number,\r\n    [Relationship_Two] = @Relationshiptwo,\r\n    [Spouse_Name] = @Spouse_Name,\r\n    [Legal_Beneficiary_Two] = @Legalbeneficiarytwo,\r\n    [Contact_Number_of_Spouse] = @Contact_Number_Spouse,\r\n    [Contact_Number_Two] = @Contact_Number_Two,\r\n    [Legal_Beneficiary_One] = @Legal_Beneficiary_One,\r\n    [Contact_Number_one] = @Contact_No_One,\r\n    [Relationship_One] = @Relationship_One,\r\n    [Created_By] = @Created_By,\r\n    [Created_On] = GETDATE(),\r\n\t[Spouse_Contact_No_CC] =@Spouse_Contact_No_CC,\r\n\t[Contact_No_Two_CC] =@Contact_No_Two_CC,\r\n\t[Contact_No_One_CC]=@Contact_No_One_CC\r\nWHERE \r\n    [Worker_id] = @WorkerId1;\r\n\r\n\r\n\r\n\tUPDATE [Tbl_Worker_EmployerInfo]\r\nSET\r\n    [SOC_ROC_ROC_No] = @SOC_ROC_ROC_No,\r\n    [Employer_Name] = @Employer_Name,\r\n    [Employer_Address] = @Employer_Address,\r\n    [Sector] = @Sector,\r\n    [Sub_Sector] = @Sub_Sector,\r\n    [Telephone_No] = @Telephone_No,\r\n    [Contact_Person] = @Contact_Person,\r\n    [Contact_Person_IC_NO] = @Contact_Person_IC_No,\r\n    [Position] = @Position,\r\n    [HP_Number] = @hp_Number,\r\n    [Email] = @Email,\r\n    [Contract_Expiry_Date] = @Contract_Expiry_Date,\r\n    [Contract_Issue_Date] = @Contract_issue_Date,\r\n    [Employment_Description] = @Employment_Description,\r\n    [Created_By] = @Created_By,\r\n    [Created_On] = GETDATE(),\r\n\t[TelephonenoCC] =@TelephonenoCC\r\nWHERE\r\n    [Worker_Id] = @WorkerId1;\r\n\r\n\r\n\r\n\r\n\tUPDATE [Tbl_Worker_RecruitAgent]\r\nSET\r\n    [Malaysian_Reqruitment_Agency] = @Malaysian_Reqruitment_Agency,\r\n    [Source_Country_Requirtment_Agency] = @Source_Country_Requirtment_Agency,\r\n    [License_No_M] = @License_No_M,\r\n    [License_No_S] = @Licenrse_NO_S,\r\n    [Address_M] = @Address_M,\r\n    [Address_S] = @Address_S,\r\n    [Email_Address_M] = @Email_Address_M,\r\n    [Email_Address_S] = @Email_Address_S,\r\n    [Contact_Person_M] = @Contact_Person_M,\r\n    [Contact_Person_S] = @Contact_Person_S,\r\n    [Contact_Number_M] = @Contact_Number_M,\r\n    [Contact_Number_S] = @Contact_Number_S,\r\n    [Website_M] = @Website_M,\r\n    [Website_S] = @Website_S,\r\n    [Created_By] = @Created_By,\r\n    [Created_On] = GETDATE(),\r\n\t[Contact_No_S_CC] =@Contact_No_S_CC,\r\n\t[Contact_N0_M_CC]=@Contact_N0_M_CC\r\nWHERE\r\n    [Worker_Id] = @WorkerId1;\r\n\r\n\r\n\r\n--\tUPDATE [Tbl_Worker_Attachments]\r\n--SET\r\n--    [Passport_Copy_Filename] = @Passportcopyfilename,\r\n--    [Passport_Copy] = @Passport_Copy,\r\n--    [Permit_Copy_Filename] = @Permitcopyfilename,\r\n--    [Permit_Copy] = @Permit_Copy,\r\n--    [Demand_Letter_Filename] = @demandletterfilename,\r\n--    [Demand_Letter] = @Demand_Letter,\r\n--    [Employment_Contract_Filename] = @Employmentcontractfilename,\r\n--    [Employment_Contract] = @Employment_Contract,\r\n--    [Insurance_Policy_Filename] = @Insurancepolicyfilename,\r\n--    [Insurance_Policy] = @Insurance_Policy,\r\n--    [Created_By] = @Created_By,\r\n--    [Created_On] = GETDATE()\r\n--WHERE\r\n--    [Worker_Id] = @WorkerId1;\r\n\r\n\r\nEnd\r\n\r\nelse if(@action='GetByWorker_ID')\r\nBegin\r\n-- Select from Tbl_Worker_PersonalInfo where Worker_id matches @Worker_Id\r\nSELECT * \r\nFROM [dbo].[Tbl_Worker_PersonalInfo] \r\nWHERE Worker_id = @Worker_Id;\r\n\r\n-- Select from Tbl_Worker_PermitInsurance where Worker_id matches @Worker_Id\r\nSELECT * \r\nFROM [dbo].[Tbl_Worker_PermitInsurance] \r\nWHERE Worker_id = @Worker_Id;\r\n\r\n-- Select from Tbl_Worker_EmployerInfo where Worker_id matches @Worker_Id\r\nSELECT * \r\nFROM [dbo].[Tbl_Worker_EmployerInfo] \r\nWHERE Worker_id = @Worker_Id;\r\n\r\n-- Select from Tbl_Worker_RecruitAgent where Worker_id matches @Worker_Id\r\nSELECT * \r\nFROM [dbo].[Tbl_Worker_RecruitAgent] \r\nWHERE Worker_id = @Worker_Id;\r\n\r\n-- Select from Tbl_Worker_Attachments where Worker_id matches @Worker_Id\r\nSELECT * \r\nFROM [dbo].[Tbl_Worker_Attachments] \r\nWHERE Worker_id = @Worker_Id;\r\n\r\nEnd\r\n\r\nelse if(@action='Getcityname')\r\nBegin\r\n\r\nselect * from Tbl_City where ID=@id;\r\nend\r\n\r\nelse if(@action = 'GetNationality')\r\nBegin\r\n\r\nselect * from Tbl_Country where ID=@id;\r\nend\r\n\r\nelse if(@action ='GetBranch')\r\nBegin\r\nselect * from Tbl_Branch where ID=@id;\r\nend\r\n\r\nelse if(@action ='GetState')\r\nBegin\r\nselect * from Tbl_State where ID=@id;\r\nend\r\n\r\nelse if(@action ='GetSourceCountryinsurance')\r\nBegin\r\nselect * from Tbl_SourceCountry_Insurance where ID =@id;\r\nend\r\n\r\nelse if(@action ='GetMalaysiainsurance')\r\nBegin\r\nselect * from [dbo].[Tbl_Insurance] where ID=@id;\r\nend\r\n\r\nelse if(@action ='GetSector')\r\nBegin\r\nselect * from [dbo].[Tbl_Sector] where ID=@id;\r\nend\r\n\r\nelse if(@action ='GetSubsector')\r\nBegin\r\nselect * from [dbo].[Tbl_SubSector] where ID=@id;\r\nend\r\nelse if(@action ='GetMarital')\r\nBegin\r\nselect * from [dbo].[Tbl_MaritalStatus] where ID=@id;\r\nend\r\n\r\n-- Inside your stored procedure (AddWorker)\r\nelse if (@action = 'GetEmployer')\r\nbegin\r\n    SELECT User_Id AS ID, Employer_Name\r\n    FROM [dbo].[Tbl_Employer]\r\n    \r\n    UNION\r\n    \r\n    SELECT User_Id AS ID, Employer_Name\r\n    FROM [dbo].[Tbl_EmployerIndividual];\r\nend\r\n\r\nelse if(@action ='GetEmpName')\r\nBegin \r\n\r\n\r\n\r\nSELECT Employer_Name\nFROM [dbo].[Tbl_EmployerIndividual]\nWHERE User_Id = @EmpId\nUNION\nSELECT Employer_Name\nFROM [dbo].[Tbl_Employer]\nWHERE User_Id = @EmpId;\r\n\r\nend\r\n\r\nelse if(@action ='GetSubvalues')\r\nbegin\r\nif(@subvalue = 'SubsectorValue')\r\nbegin\r\nselect ID from [dbo].[Tbl_SubSector] WHERE SubSector_Name=@SubName;\r\nend\r\nelse if(@subvalue = 'StateValue')\r\nbegin\r\nselect ID from [dbo].[Tbl_State] where State_Name = @SubName;\r\nend\r\nelse if(@subvalue ='CityValue')\r\nbegin\r\nselect ID from [dbo].[Tbl_City] where City_Name = @SubName;\r\nend\r\nend\r\n\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='AddWorker' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[Ads_Get_Country]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Country' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[Ads_Get_Country]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- =============================================\r\nCREATE PROCEDURE [dbo].[Ads_Get_Country]\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n\tSELECT Id,Country_Name from Tbl_Country WHERE Country_Status='1'\r\nEND\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Country' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_typ