\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='Ads_Get_Menu' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[CreateWorker]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='CreateWorker' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[CreateWorker]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[CreateWorker] \r\n\t--\"Personal Information\"\r\n         @Name varchar(MAX),--NOT NULL\r\n\r\n        @Passport_Number varchar(MAX),--NOT NULL\r\n\r\n        @Passport_Issue_Date varchar(MAX)=NULL,\r\n\r\n        @Passport_Expiry_Date varchar(MAX),--NOT NULL\r\n\r\n        @Address varchar(MAX),--NOT NULL\r\n\r\n        @District varchar(MAX)=NULL,\r\n\r\n        @City varchar(MAX)=NULL,\r\n\r\n        @Nationality varchar(MAX),--NOT NULL\r\n\r\n\r\n        @State varchar(MAX)=NULL,\r\n\r\n        @Gender varchar(MAX)=NULL,\r\n\r\n        @DOB varchar(MAX),--NOT NULL\r\n\r\n        @ContactNumber varchar(MAX)=NULL,\r\n\r\n        @Marital_Status varchar(MAX)=NULL,\r\n\r\n        @Highest_Education varchar(MAX)=NULL,\r\n\r\n        @Email_Id varchar(MAX)=NULL,\r\n\r\n        @Mother_Name varchar(MAX)=NULL,\r\n\r\n        @Father_Name varchar(MAX)=NULL,\r\n\r\n       @Branch varchar(MAX)=NULL,\r\n\r\n\t   @photoname varchar(250)=null,\r\n\r\n        @photo varchar(MAX)=NULL,\r\n        \r\n\r\n\r\n        --#region Permit Status And Insurance\r\n\r\n        @Permit_Issue_Date varchar(MAX)=NULL,\r\n\r\n        @Permit_Expire_Date varchar(MAX),--NOT NULL\r\n\r\n        @Permit_Issue_Place varchar(MAX)=NULL,\r\n\r\n        @Insurance_Policy_No varchar(MAX)=NULL,\r\n\r\n        @Source_Country_Insurance varchar(MAX)=NULL,\r\n\r\n        @Malaysia_Insurance varchar(MAX)=NULL,\r\n\r\n        @SOSCO_Number varchar(MAX)=NULL,\r\n\r\n        @Relationshiptwo varchar(MAX)=NULL,\r\n\r\n        @Spouse_Name varchar(MAX)=NULL,\r\n\r\n        @Legalbeneficiarytwo varchar(MAX)=NULL,\r\n\r\n        @Contact_Number_Spouse varchar(MAX)=NULL,\r\n\r\n        @Contact_Number_Two varchar(MAX)=NULL,\r\n\r\n        @Legal_Beneficiary_One varchar(MAX)=NULL,\r\n\r\n        @Contact_No_One varchar(MAX)=NULL,\r\n\r\n        @Relationship_One varchar(MAX)=NULL,\r\n        \r\n\r\n--# region \"Employer Information\"\r\n\r\n        @SOC_ROC_ROC_No varchar(MAX)=NULL,\r\n\r\n        @Employer_Name varchar(MAX)=NULL,\r\n\r\n        @Employer_Address varchar(MAX) =NULL,\r\n\r\n        @Sector varchar(MAX)=NULL,\r\n\r\n        @Sub_Sector varchar(MAX)=NULL,\r\n\r\n        @Telephone_No varchar(MAX)=NULL,\r\n\r\n        @Contact_Person varchar(MAX)=NULL,\r\n\r\n        @Contact_Person_IC_No varchar(MAX)=NULL,\r\n\r\n        @Position varchar(MAX)=NULL,\r\n\r\n        @hp_Number varchar(MAX)=NULL,\r\n\r\n        @Email varchar(MAX)=NULL,\r\n\r\n        @Contract_Expiry_Date varchar(MAX)=NULL,\r\n\r\n        @Contract_issue_Date varchar(MAX)=NULL,\r\n\r\n        @Employment_Description varchar(MAX)=NULL,\r\n        \r\n\r\n--# region Reqruitment Agents\r\n\r\n        @Malaysian_Reqruitment_Agency varchar(MAX)=NULL,\r\n\r\n        @Source_Country_Requirtment_Agency varchar(MAX)=NULL,\r\n\r\n        @License_No_M varchar(MAX)=NULL,\r\n\r\n        @Licenrse_NO_S varchar(MAX)=NULL,\r\n\r\n        @Address_M varchar(MAX)=NULL,\r\n\r\n        @Address_S varchar(MAX)=NULL,\r\n\r\n        @Email_Address_M varchar(MAX)=NULL,\r\n\r\n        @Email_Address_S varchar(MAX)=NULL,\r\n\r\n        @Contact_Person_M varchar(MAX)=NULL,\r\n\r\n        @Contact_Person_S varchar(MAX)=NULL,\r\n\r\n        @Contact_Number_M varchar(MAX)=NULL,\r\n\r\n        @Contact_Number_S varchar(MAX)=NULL,\r\n\r\n        @Website_M varchar(MAX)=NULL,\r\n\r\n        @Website_S varchar(MAX)=NULL,\r\n        \r\n\r\n--# region Attachment\r\n       @Passportcopyfilename varchar(250)=null,\r\n        @Passport_Copy varchar(MAX)=NULL,\r\n\t\t@Permitcopyfilename varchar(250)=null,\r\n         @Permit_Copy varchar(MAX)=NULL,\r\n\t\t @demandletterfilename varchar(250)=null,\r\n        @Demand_Letter varchar(MAX)=NULL,\r\n\t\t@Employmentcontractfilename varchar(250)=null,\r\n        @Employment_Contract varchar(MAX)=NULL,\r\n\t\t@Insurancepolicyfilename varchar(250)=null,\r\n        @Insurance_Policy varchar(MAX)=NULL\r\n        \r\n\r\nAS\r\nBEGIN\r\n\tINSERT INTO [dbo].[Tbl_Worker]\n           ([Name], [Passport_Number], [Passport_Issue_Date], [Passport_Expire_Date],\n            [Address], [District], [City], [Nationality], [State], [Gender], [Date_of_Birth],\n            [Contact_Number], [Marital_Status], [Highest_Education], [Email_Id], [Mother_Name],\n            [Father_Name], [Branch], [Photoname],[Photo], [Permit_Issue_Date], [Permit_Expiry_Date], \n            [Permit_Issue_Place], [Insurance_Policy_No], [Source_Country_Insurance], \n            [Malaysia_Insurance], [SOSCO_Number], [Relationship_Two], [Spouse_Name], \n            [Legal_Beneficiary_Two], [Contact_No_Spouse], [Contact_No_Two], [Legal_Beneficiary_One],\n            [Contact_No_One], [Relationship_One], [SSM_ROC_RON_NO], [Employer_Name], [Employer_Address],\n            [Sector], [Sub_Sector], [Telephone_No], [Contact_Person], [Contact_Person_IC_NO],\n            [Position], [HP_Number], [Email], [Contract_Expiry_Date], [Contract_Issue_Date], \n            [Employment_Description], [Malaysian_Reqruitment_Agency], [Source_Country_Reqruitment_Agency],\n            [License_No_M], [License_No_S], [Address_M], [Addres_S], [Email_Address_M], \n            [Email_Address_S], [Contact_Person_M], [Contact_Person_S], [Contact_Number_M], \n            [Contact_Number_S], [Website_M], [Website_S],[Passportcopyfilename], [Passport_Copy],[Permitcopyfilename], [Permit_Copy], \n            [demandletterfilename],[Demand_Letter],[employmentcontractfilename], [Employment_Contract],[Insurancepolicyfilename], [Insurance_Policy])\n    VALUES\n           (@Name, @Passport_Number, @Passport_Issue_Date, @Passport_Expiry_Date,\n            @Address, @District, @City, @Nationality, @State, @Gender, @DOB, \n            @ContactNumber, @Marital_Status, @Highest_Education, @Email_Id, @Mother_Name,\n            @Father_Name, @Branch,@photoname, @photo, @Permit_Issue_Date, @Permit_Expire_Date, \n            @Permit_Issue_Place, @Insurance_Policy_No, @Source_Country_Insurance, \n            @Malaysia_Insurance, @SOSCO_Number, @Relationshiptwo, @Spouse_Name, \n            @Legalbeneficiarytwo, @Contact_Number_Spouse, @Contact_Number_Two, \n            @Legal_Beneficiary_One, @Contact_No_One, @Relationship_One, \n            @SOC_ROC_ROC_No, @Employer_Name, @Employer_Address, @Sector, @Sub_Sector, \n            @Telephone_No, @Contact_Person, @Contact_Person_IC_No, @Position, \n            @hp_Number, @Email, @Contract_Expiry_Date, @Contract_issue_Date, \n            @Employment_Description, @Malaysian_Reqruitment_Agency, \n            @Source_Country_Requirtment_Agency, @License_No_M, @Licenrse_NO_S, \n            @Address_M, @Address_S, @Email_Address_M, @Email_Address_S, \n            @Contact_Person_M, @Contact_Person_S, @Contact_Number_M, \n            @Contact_Number_S, @Website_M, @Website_S, @Passportcopyfilename,@Passport_Copy,@Permitcopyfilename, @Permit_Copy, \n            @demandletterfilename,@Demand_Letter,@Employmentcontractfilename, @Employment_Contract,@Insurancepolicyfilename, @Insurance_Policy);\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='CreateWorker' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[GetUserMenu]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='GetUserMenu' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[GetUserMenu]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\t<Author,,Name>\r\n-- Create date: <Create Date,,>\r\n-- Description:\t<Description,,>\r\n-- ===========================================\r\n\r\n\r\nCREATE PROCEDURE [dbo].[GetUserMenu] \r\n\t @UserId NVARCHAR(100)\r\nAS\r\nBEGIN\r\n\t-- SET NOCOUNT ON added to prevent extra result sets from\r\n\t-- interfering with SELECT statements.\r\n\tSET NOCOUNT ON;\r\n\r\n    -- Insert statements for procedure here\r\n\t\r\nselect distinct d.User_ID,d.User_Name, d.User_Status as 'UserStatus',d.User_Role,a.Menu_ID,a.ISDefault,b.PAGE_NAME,b.PAGE_URL,--b.IMAGE,\r\nc.Role_Status as RoleStatus,b.parent_id  from\r\nTbl_Rights_Master a,Tbl_Menu_Details b,TBL_ROLE c,tbl_user d\r\nwhere a.Menu_ID=b.ID and a.Role_ID=c.ID and d.User_Role=a.Role_ID\r\nand d.User_Id=@UserId\r\nEND\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='GetUserMenu' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateBranch]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateBranch' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateBranch]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateBranch]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@BranchName  VARCHAR(50),\r\n\t\t@BranchShortName VARCHAR(10),\r\n\t\t@BranchStatus INT,\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_BRANCH WHERE Branch_Name = @BranchName AND Branch_ShortName =@BranchShortName)\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_BRANCH (Branch_Name,Branch_ShortName,Branch_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@BranchName, @BranchShortName,@BranchStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_BRANCH SET Branch_Name = @BranchName, Branch_ShortName = @BranchShortName,Branch_Status=@BranchStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID,Branch_Name,Branch_ShortName,Branch_Status FROM TBL_BRANCH  \r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID,Branch_Name,Branch_ShortName,Branch_Status FROM TBL_BRANCH  \r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 19-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID,Branch_Name,Branch_ShortName,Branch_Status FROM TBL_BRANCH  where ID=@ID;   \r\n\t\t\tEND\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[Tbl_Branch]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateBranch '','INSERT','Navi Mumbai','NM','1',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateBranch '','','Navi Mumbai','NM','1',''\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateBranch' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateCity]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateCity' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateCity]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateCity]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@Countryid INT,\r\n\t\t@Stateid INT,\r\n\t\t@CityName  VARCHAR(50),\r\n\t\t@CityShortName VARCHAR(10),\t\t\r\n\t\t@CityStatus INT,\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_CITY WHERE City_Name = @CityName AND City_ShortName =@CityShortName)\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_CITY (Country_ID,State_ID,City_Name,City_ShortName,City_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@Countryid, @Stateid,@CityName,@CityShortName,@CityStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_CITY SET Country_ID = @Countryid, State_ID = @Stateid, City_Name=@CityName,City_ShortName=@CityShortName,City_Status=@CityStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\t\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select ct.ID, ct.Country_ID, ct.State_ID, ct.City_Name, ct.City_ShortName, ct.City_Status, st.state_name,co.country_name from tbl_city ct left join tbl_state  st  on   ct.State_ID= st.ID  left join Tbl_Country co  on ct.Country_ID=co.ID;\r\n\t\t\tEND\t\r\n\t\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select ct.ID, ct.Country_ID, ct.State_ID, ct.City_Name, ct.City_ShortName, ct.City_Status, st.state_name,co.country_name from tbl_city ct left join tbl_state  st  on   ct.State_ID= st.ID  left join Tbl_Country co  on ct.Country_ID=co.ID where ct.City_Status='1';\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 18-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Country_ID, State_ID, City_Name, City_ShortName, City_Status FROM TBL_CITY WHERE ID=@ID;\r\n\t\t\tEND\t\r\n\r\n\t\t\t--Added By Chandrashekhar to get city based on stateid\r\n\t\t\tElse IF @Action='GETCITY'\r\n\t\t\tBEGIN\r\n\t\t\t    Select ID,City_Name from Tbl_City Where State_ID= @Stateid and City_Status='1';\r\n\t\t\tEND\r\n\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_CITY]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateCity '','INSERT',3,1,'Mumbai','MUM',1,''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateCity '3','UPDATE','3','1','Mumbai','MUM','0',''\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateCity' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateCountry]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateCountry' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateCountry]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateCountry]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@CountryName  VARCHAR(50),\r\n\t\t@CountryShortName VARCHAR(10),\r\n\t\t@CountryFlag VARBINARY(MAX)=null,\r\n\t\t@CountryStatus INT,\r\n\t\t@CountryCode VARCHAR(10) = null,\r\n\t\t@FlagPath NVARCHAR(255) = null,\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_COUNTRY WHERE Country_Name = @CountryName AND Country_ShortName =@CountryShortName)\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_COUNTRY (Country_Name,Country_ShortName,Country_Flag,Country_Status,Created_By,Created_On,countrycode,FlagPath) \r\n\t\t\t\t\t\tVALUES(@CountryName, @CountryShortName,@CountryFlag,@CountryStatus,'ADMIN', GETDATE(),@CountryCode,@FlagPath)  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_COUNTRY SET Country_Name = @CountryName, Country_ShortName = @CountryShortName,Country_Flag=@CountryFlag,Country_Status=@CountryStatus,countrycode=@CountryCode,FlagPath=@FlagPath WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Country_Name, Country_ShortName, Country_Flag, Country_Status,countrycode,FlagPath FROM TBL_COUNTRY \r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Country_Name, Country_ShortName, Country_Flag, Country_Status FROM TBL_COUNTRY WHERE Country_Status='1'\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 19-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Country_Name, Country_ShortName, Country_Flag, Country_Status,countrycode,FlagPath FROM TBL_COUNTRY WHERE ID=@ID ;\r\n\t\t\tEND\t\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_COUNTRY]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateCountry '','INSERT','India','IND','III','1',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateCountry '1','UPDATE','Malaysia','MAL','MMM','1',''\r\n\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateCountry' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateDepartment]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateDepartment' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateDepartment]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateDepartment]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@DepartmentName  VARCHAR(50),\r\n\t\t@DepartmentStatus VARCHAR(10),\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_DEPARTMENT WHERE Department_Name = @DepartmentName)\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_DEPARTMENT (Department_Name,Department_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@DepartmentName, @DepartmentStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_DEPARTMENT SET Department_Name = @DepartmentName, Department_Status = @DepartmentStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Department_Name,Department_Status FROM TBL_DEPARTMENT ;\r\n\t\t\tEND\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Department_Name,Department_Status FROM TBL_DEPARTMENT where department_status='1';\r\n\t\t\tEND\r\n\t\t\t-- Added by Nandkishor on 19-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Department_Name,Department_Status FROM TBL_DEPARTMENT where ID=@ID;\r\n\t\t\tEND\t\t\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_DEPARTMENT]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateDepartment '','INSERT','Operations',1,''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateDepartment '5','UPDATE','Operations','1',''\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateDepartment' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateInsurance]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateInsurance' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateInsurance]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateInsurance]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@InsuranceName  VARCHAR(50),\r\n\t\t@InsuranceShortName  VARCHAR(10),\r\n\t\t@InsuranceNationality INT,\r\n\t\t@InsuranceStatus INT,\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_INSURANCE WHERE Insurance_Name = @InsuranceName and Insurance_ShortName=@InsuranceShortName)\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_INSURANCE (Insurance_Name,Insurance_ShortName,Insurance_Nationality, Insurance_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@InsuranceName,@InsuranceShortName,@InsuranceNationality, @InsuranceStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_INSURANCE SET Insurance_Name = @InsuranceName,Insurance_ShortName=@InsuranceShortName,Insurance_Nationality=@InsuranceNationality, Insurance_Status = @InsuranceStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT  i.ID, i.Insurance_Name, i.Insurance_ShortName, i.Insurance_Nationality, i.Insurance_Status,ct.country_name,ct.id FROM  tBL_insurance  i  inner join tbl_country ct on i.Insurance_Nationality=ct.id;\r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT  i.ID, i.Insurance_Name, i.Insurance_ShortName, i.Insurance_Nationality, i.Insurance_Status,ct.country_name,ct.id FROM  tBL_insurance  i  left join tbl_country ct on i.Insurance_Nationality=ct.id WHERE i.insurance_status='1';\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 18-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tSELECT  i.ID, i.Insurance_Name, i.Insurance_ShortName, i.Insurance_Nationality, i.Insurance_Status,ct.country_name,ct.id FROM  tBL_insurance  i  inner join tbl_country ct on i.Insurance_Nationality=ct.id WHERE i.ID=@ID;\r\n\t\t\tEND\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_INSURANCE]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateInsurance '','INSERT','Allianz General','AMG','1','1',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateInsurance '1','UPDATE','Allianz Life','AML','1','1',''\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateInsurance' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateMaritalStatus]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateMaritalStatus' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateMaritalStatus]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateMaritalStatus]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@MaritalStatus  VARCHAR(50)=null,\t\t\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_MARITALSTATUS WHERE Marital_Status = @MaritalStatus )\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_MARITALSTATUS (Marital_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@MaritalStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_MARITALSTATUS SET Marital_Status = @MaritalStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tSELECT ID, Marital_Status FROM TBL_MARITALSTATUS;\r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tSELECT ID, Marital_Status FROM TBL_MARITALSTATUS WHERE ID=@ID;\r\n\t\t\tEND\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_MARITALSTATUS]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateMaritalStatus '','INSERT','Living common law',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateMaritalStatus '5','UPDATE','Living Common Law',''\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateMaritalStatus' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateRole]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateRole' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateRole]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateRole]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@RoleName VARCHAR(50),\r\n\t\t@RoleStatus  INT,\t\t\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_ROLE WHERE Role_Name = @RoleName )\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_ROLE (Role_Name,Role_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@RoleName,@RoleStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_ROLE SET Role_Name = @RoleName,Role_Status=@RoleStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Role_Name,Role_Status FROM TBL_ROLE;\r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Role_Name,Role_Status FROM TBL_ROLE WHERE role_status='1';\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 25-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Role_Name,Role_Status FROM TBL_ROLE where @ID=ID;\r\n\t\t\tEND\t\t\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_ROLE]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateRole '','INSERT','Viewer','1',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateRole '6','UPDATE','View User','0',''\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateRole' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateSCInsurance]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateSCInsurance' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateSCInsurance]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateSCInsurance]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@SCInsuranceName  VARCHAR(50),\r\n\t\t@SCInsuranceShortName  VARCHAR(10),\r\n\t\t@SCInsuranceNationality INT,\r\n\t\t@SCInsuranceStatus INT,\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_SOURCECOUNTRY_INSURANCE WHERE SC_Insurance_Name = @SCInsuranceName and SC_Insurance_ShortName=@SCInsuranceShortName)\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_SOURCECOUNTRY_INSURANCE (SC_Insurance_Name,SC_Insurance_ShortName,SC_Insurance_Nationality, SC_Insurance_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@SCInsuranceName,@SCInsuranceShortName,@SCInsuranceNationality, @SCInsuranceStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_SOURCECOUNTRY_INSURANCE SET SC_Insurance_Name = @SCInsuranceName,SC_Insurance_ShortName=@SCInsuranceShortName,SC_Insurance_Nationality=@SCInsuranceNationality, SC_Insurance_Status = @SCInsuranceStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select  SI.ID, SI.SC_Insurance_Name, SI.SC_Insurance_ShortName, SI.SC_Insurance_Nationality, SI.SC_Insurance_Status,ct.country_name,ct.id  from TBL_SOURCECOUNTRY_INSURANCE  SI  inner join tbl_Country  ct on si.SC_Insurance_Nationality=ct.id;\r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select  SI.ID, SI.SC_Insurance_Name, SI.SC_Insurance_ShortName, SI.SC_Insurance_Nationality, SI.SC_Insurance_Status,ct.country_name,ct.id  from TBL_SOURCECOUNTRY_INSURANCE  SI  left join tbl_Country  ct on si.SC_Insurance_Nationality=ct.id WHERE SC_Insurance_Status='1';\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 24-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select  SI.ID, SI.SC_Insurance_Name, SI.SC_Insurance_ShortName, SI.SC_Insurance_Nationality, SI.SC_Insurance_Status,ct.country_name,ct.id  from TBL_SOURCECOUNTRY_INSURANCE  SI  inner join tbl_Country  ct on si.SC_Insurance_Nationality=ct.id where SI.ID=@ID;\r\n\t\t\tEND\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_SOURCECOUNTRY_INSURANCE]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateSCInsurance '','INSERT','Allianz General','AMG','1','1',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateSCInsurance '1','UPDATE','Allianz Life','AML','1','1',''\r\n\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateSCInsurance' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateSector]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateSector' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateSector]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- ===========================