S_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateSector' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateState]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateState' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateState]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateState]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@Countryid INT,\t\r\n\t\t@StateName  VARCHAR(50),\r\n\t\t@StateShortName VARCHAR(10),\t\t\r\n\t\t@StateStatus INT,\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_STATE WHERE State_Name = @StateName AND State_ShortName =@StateShortName)\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_STATE (Country_ID,State_Name,State_ShortName,State_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@Countryid, @StateName,@StateShortName,@StateStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_STATE SET Country_ID = @Countryid, State_Name = @StateName, State_ShortName=@StateShortName,State_Status=@StateStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select st.ID, st.Country_ID, st.State_Name, st.State_ShortName, st.State_Status, st.Created_By, st.Created_On,country_name from tbl_state  st left join tbl_country ct on Country_ID=ct.id\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Saurabh Singh on 08-01-2025\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select st.ID, st.Country_ID, st.State_Name, st.State_ShortName, st.State_Status, st.Created_By, st.Created_On,country_name from tbl_state  st inner join tbl_country ct on Country_ID=ct.id where st.State_Status='1';\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 26-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select st.ID, st.Country_ID, st.State_Name, st.State_ShortName, st.State_Status, st.Created_By, st.Created_On,country_name from tbl_state  st inner join tbl_country ct on Country_ID=ct.ID  WHERE ST.ID=@ID;\r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'slt_drp'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select st.ID, st.Country_ID, st.State_Name, st.State_ShortName, st.State_Status, st.Created_By, st.Created_On,country_name from tbl_state  st inner join tbl_country ct on Country_ID=ct.ID  ;\r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action='GETSTATE' \r\n\t\t\tBEGIN\r\n\t\t\t    select st.ID,st.State_Name from tbl_state as st where Country_ID=@Countryid and state_status=1; --Added to get state id and name based on country id\r\n\t\t\tEND\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_STATE]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateState '','INSERT',1,'Johor','JOH',1,''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateState '3','UPDATE','1','Johor','JOH','1',''\r\n\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateState' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateStatus]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateStatus' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateStatus]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateStatus]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@Status  VARCHAR(50),\t\t\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_STATUS WHERE status = @Status )\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_STATUS (Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@Status,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_STATUS SET Status = @Status WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tSELECT ID, Status FROM TBL_STATUS;\r\n\t\t\tEND\t\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_STATUS]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateStatus '','INSERT','Hold',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateStatus '3','UPDATE','Hold',''\r\n\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateStatus' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateSubSector]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateSubSector' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateSubSector]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateSubSector]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@SectorID  INT,\r\n\t\t@SubSectorName VARCHAR(50),\r\n\t\t@SubSectorStatus  INT,\t\t\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_SUBSECTOR WHERE Sector_ID=@SectorID and SubSector_Name = @SubSectorName )\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_SUBSECTOR (Sector_ID,SubSector_Name,SubSector_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@SectorID,@SubSectorName,@SubSectorStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_SUBSECTOR SET Sector_ID = @SectorID,SubSector_Name=@SubSectorName,SubSector_Status=@SubSectorStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select sb.ID, sb.Sector_ID, sb.SubSector_Name, sb.SubSector_Status, s.Sector_Name,S.ID from tbl_subsector sb left join tbl_sector s  on sb.Sector_ID=s.ID;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Saurabh Singh on 16-12-2024\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select sb.ID, sb.Sector_ID, sb.SubSector_Name, sb.SubSector_Status, s.Sector_Name,S.ID from tbl_subsector sb left join tbl_sector s  on sb.Sector_ID=s.ID where sb.SubSector_Status='1';\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 26-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select sb.ID, sb.Sector_ID, sb.SubSector_Name, sb.SubSector_Status, s.Sector_Name,S.ID from tbl_subsector sb left join tbl_sector s  on sb.Sector_ID=s.ID WHERE sb.ID=@ID;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 09/01/2024\r\n\t\t\tELSE IF @Action = 'SELECT_FOR_EMPLOYER_SIGNUP'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t select sb.ID, sb.Sector_ID, sb.SubSector_Name, sb.SubSector_Status, s.Sector_Name,S.ID from tbl_subsector sb left join tbl_sector s  on sb.Sector_ID=s.ID where sb.SubSector_Status='1' AND  sb.Sector_ID =@SectorID;\r\n\t\t\tEND\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_SUBSECTOR]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateSubSector '','INSERT','4','Others','1',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateSubSector '3','UPDATE','4','Other SubSector','1',''\r\n\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateSubSector' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUpdateTitle]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateTitle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUpdateTitle]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- =============================================\r\n-- Author:\t\tSankar Mahalingam\r\n-- Create date: 11.12.2024\r\n-- Description:\tInsert / Update Branch Master Table.\r\n-- =============================================\r\nCREATE  PROCEDURE [dbo].[InsertUpdateTitle]\r\n\r\n\t\t@ID  INT,\r\n\t\t@Action  VARCHAR(50),\r\n\t\t@TitleName VARCHAR(50),\r\n\t\t@TitleStatus  INT,\t\t\r\n\t\t@Result INT OUTPUT\r\n\r\nAS\r\nBEGIN\t\r\n\tSET NOCOUNT ON;\r\n\t\tIF @Action = 'INSERT'\r\n\t\t\tBEGIN\r\n\t\t\t\tIF EXISTS(SELECT ID FROM TBL_TITLE WHERE Title_Name = @TitleName )\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tSET @Result = 0;\r\n\t\t\t\t\tEND\r\n\t\t\t\tELSE\r\n\t\t\t\t\tBEGIN\r\n\t\t\t\t\t\tINSERT INTO TBL_TITLE (Title_Name,Title_Status,Created_By,Created_On) \r\n\t\t\t\t\t\tVALUES(@TitleName,@TitleStatus,'ADMIN', GETDATE())  \t\t\t\r\n\t\t\t\t\t\tSET @Result = 1;\r\n\t\t\t\t\tEND\t\r\n\t\t\t\tEND\r\n\t\tELSE IF @Action = 'UPDATE'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\tUPDATE TBL_TITLE SET Title_Name = @TitleName,Title_Status=@TitleStatus WHERE ID = @ID \r\n\t\t\t\tSET @Result = 2;\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 16-12-2024\r\n\t\t\tELSE IF @Action = 'LIST'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Title_Name,Title_Status FROM TBL_TITLE;\r\n\t\t\tEND\t\r\n\t\t\tELSE IF @Action = 'SELECT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Title_Name,Title_Status FROM TBL_TITLE WHERE Title_Status='1';\r\n\t\t\tEND\t\r\n\t\t\t-- Added by Nandkishor on 26-12-2024\r\n\t\t\tELSE IF @Action = 'EDIT'   \r\n\t\t\tBEGIN\t\t\r\n\t\t\t\t SELECT ID, Title_Name,Title_Status FROM TBL_TITLE where  ID=@ID;\r\n\t\t\tEND\t\t\t\r\n\t\tEND\r\n \r\n\r\n --SELECT * FROM [dbo].[TBL_TITLE]\r\n\r\n --INSERT SAMPLE\r\n --EXEC InsertUpdateTitle '','INSERT','Director','1',''\r\n\r\n --UPDATE SAMPLE\r\n --EXEC InsertUpdateTitle '3','UPDATE','Director','0',''\r\n\r\n\r\n\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUpdateTitle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[InsertUser]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUser' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[InsertUser]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[InsertUser]\r\n    @User_Id NVARCHAR(100),\r\n    @EmailId NVARCHAR(100),\r\n    @StatusId INT,\r\n    @RoleId INT,\r\n\t@UserTitle INT,\r\n    @BranchId INT,\r\n    @CreatedBy NVARCHAR(50),\r\n    @Result INT OUTPUT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    BEGIN TRY\r\n        INSERT INTO Tbl_User (User_Id, Email_Id, User_Status, User_Role,User_Title, User_Branch, Created_By, Created_On)\r\n        VALUES (@User_Id, @EmailId, @StatusId, @RoleId,@UserTitle, @BranchId, @CreatedBy, GETDATE());\r\n\r\n        SET @Result = 1; -- Success\r\n    END TRY\r\n    BEGIN CATCH\r\n        SET @Result = 0; -- Failure\r\n    END CATCH\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='InsertUser' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[LoginInsertUser]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='LoginInsertUser' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[LoginInsertUser]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\n-- Author:\t\tAkshay\r\n-- Create date: 16.12.2024\r\n-- Description:\tcheck user status / insert tblEmployer and tblAgent Data.\r\n-- =============================================\r\nCREATE PROCEDURE [dbo].[LoginInsertUser]\r\n    @Action NVARCHAR(50), -- Action to perform ('Login', 'SubmitEmployer', or 'SubmitAgent')\r\n\t @ID INT = NULL,\r\n\t@USER_ID  NVARCHAR(100) = NULL,\r\n\t@User_Name NVARCHAR(100) = NULL,\r\n    @Email_ID NVARCHAR(100) = NULL,    \r\n    @Login_Pwd NVARCHAR(100) = NULL,\r\n\t@Title INT = NULL,\r\n\t@Role INT = NULL,\r\n\t@Branch INT = NULL,\r\n\t@Status INT = NULL,    \r\n    @Employer_Name NVARCHAR(100) = NULL, \r\n    @Employer_Address NVARCHAR(500) = NULL,\r\n    @Employer_ContactPerson NVARCHAR(100) = NULL,\r\n    @Employer_Position NVARCHAR(100) = NULL,\r\n    @Employer_EmailID NVARCHAR(100) = NULL,\r\n    @Employer_OfficeNumber NVARCHAR(20) = NULL,\r\n    @Employer_SSM_ROC_ROB_Number NVARCHAR(100) = NULL,\r\n    @Employer_Sector INT = NULL,\r\n    @Employer_SubSector INT = NULL,\r\n    @Employer_PIC_MobileNumber NVARCHAR(20) = NULL,\r\n    @Employer_Description NVARCHAR(500) = NULL,\r\n    @Employer_HFW NVARCHAR(10) = NULL,\r\n    @Employer_LFW NVARCHAR(10) = NULL,\r\n    @Employer_FWC NVARCHAR(500) = NULL,\r\n\t@Agent_Name NVARCHAR(100) = null,\r\n\t@Agent_Organization_Name NVARCHAR(100) = null,\r\n\t@Agent_IC_Passport NVARCHAR(100) = null,\r\n\t@Agent_EmailID NVARCHAR(100) = null,\r\n\t@Agent_Department NVARCHAR(100) = null,\r\n\t@Agent_Country INT = null,\r\n\t@Agent_ContactNumber NVARCHAR(100) = null,\r\n    @Created_By NVARCHAR(100) = NULL,\r\n    @Created_On DATETIME = NULL,\r\n\t@CountryCode NVARCHAR(10) = NULL\r\nAS\r\nBEGIN\r\n    BEGIN TRY\r\n        IF @Action = 'Login'\r\n        BEGIN\r\n            -- Check if Email and Password match in Tbl_User\r\n        --    IF EXISTS (SELECT 1 \r\n        --               FROM Tbl_User \r\n        --               WHERE Email_ID = @Email_ID AND Login_Pwd = @Login_Pwd)\r\n        --    BEGIN\r\n        --        SELECT User_ID,User_Name,User_Role, 'Login Successful' AS Message\r\n        --FROM Tbl_User\r\n        --WHERE Email_ID = @Email_ID AND Login_Pwd = @Login_Pwd;\r\n        --    END\r\n        --    ELSE\r\n        --    BEGIN\r\n        --        SELECT 'Login Failed: Invalid Email or Password' AS Message\r\n        --    END\r\n\r\n\t\tIF EXISTS (SELECT 1 \r\n           FROM Tbl_User \r\n           WHERE Email_ID = @Email_ID COLLATE Latin1_General_CS_AS \r\n                 AND Login_Pwd = @Login_Pwd COLLATE Latin1_General_CS_AS)\r\nBEGIN\r\n    SELECT \r\n        User_ID,\r\n        User_Name,\r\n        User_Role,\r\n        'Login Successful' AS Message\r\n    FROM Tbl_User\r\n    WHERE Email_ID = @Email_ID COLLATE Latin1_General_CS_AS \r\n          AND Login_Pwd = @Login_Pwd COLLATE Latin1_General_CS_AS;\r\nEND\r\nELSE\r\nBEGIN\r\n    SELECT 'Login Failed: Invalid Email or Password' AS Message;\r\nEND\r\n\r\n        END\r\n        ELSE IF @Action = 'SubmitEmployer'\r\n        BEGIN\r\n            INSERT INTO Tbl_Employer (user_id,\r\n                Employer_Name, Employer_Address, Employer_ContactPerson, Employer_Position,\r\n                Employer_EmailID, Employer_OfficeNumber, Employer_SSM_ROC_ROB_Number, Employer_Sector,\r\n                Employer_SubSector, Employer_PIC_MobileNumber, Employer_Description,Employer_HFW,Employer_LFW, Employer_FWC,\r\n                Created_By, Created_On,CountryCode\r\n            )\r\n            VALUES (@USER_ID,\r\n                @Employer_Name, @Employer_Address, @Employer_ContactPerson, @Employer_Position,\r\n                @Employer_EmailID, @Employer_OfficeNumber, @Employer_SSM_ROC_ROB_Number, @Employer_Sector,\r\n                @Employer_SubSector, @Employer_PIC_MobileNumber, @Employer_Description,@Employer_HFW,@Employer_LFW, @Employer_FWC,\r\n                @Created_By, GETDATE(),@CountryCode\r\n            );\r\n\r\n            -- Retrieve the identity value\r\n            DECLARE @NewId INT = SCOPE_IDENTITY();\r\n\r\n            -- Format the UserId as EMP0001\r\n            DECLARE @UserId NVARCHAR(100) = 'EMP' + RIGHT('00000' + CAST(@NewId AS NVARCHAR), 4);\r\n\r\n            -- Update the record with the generated UserId\r\n            UPDATE Tbl_Employer\r\n            SET User_Id = @UserId\r\n            WHERE Id = @NewId;\r\n\r\n            INSERT INTO Tbl_User (USER_ID, email_id, created_by, Created_On,User_Name) \r\n            VALUES (@UserId, @Employer_EmailID, @Created_By, GETDATE(),@Employer_Name);\r\n\r\n            SELECT @UserId AS UserId, 'Employer Registered Successfully' AS Message;\r\n        END\r\n        ELSE IF @Action = 'SubmitAgent'\r\n        BEGIN\r\n            INSERT INTO Tbl_Agent (user_id,\r\n                Agent_Name, Agent_Organization_Name, Agent_IC_Passport, Agent_EmailID,\r\n                Agent_Department, Agent_Country, Agent_ContactNumber,\r\n                Created_By, Created_On, Agent_CountryCode\r\n            )\r\n            VALUES (@USER_ID,\r\n                @Agent_Name, @Agent_Organization_Name, @Agent_IC_Passport, @Agent_EmailID,\r\n                @Agent_Department, @Agent_Country, @Agent_ContactNumber,\r\n                @Created_By, GETDATE(), @CountryCode\r\n            );\r\n\r\n            -- Retrieve the identity value\r\n            DECLARE @Agent_NewId INT = SCOPE_IDENTITY();\r\n\r\n            -- Format the UserId as AGT0001\r\n            DECLARE @Agent_UserId NVARCHAR(100) = 'AGT' + RIGHT('00000' + CAST(@Agent_NewId AS NVARCHAR), 4);\r\n\r\n            -- Update the record with the generated UserId\r\n            UPDATE Tbl_Agent\r\n            SET User_Id = @Agent_UserId,\r\n\t\t\tCreated_By= @Created_By\r\n            WHERE Id = @Agent_NewId;\r\n\r\n            INSERT INTO Tbl_User (USER_ID, email_id, created_by, Created_On,User_Name) \r\n            VALUES (@Agent_UserId, @Agent_EmailID, @Created_By, GETDATE(),@Agent_Name);\r\n\r\n            SELECT @Agent_UserId AS UserId, 'Agent Data Inserted Successfully' AS Message;\r\n        END\r\n\r\n\t\tELSE IF @Action = 'SubmitUser'\r\n        BEGIN\r\n\r\n            IF @ID IS NULL\r\n        BEGIN\r\n            -- Insert new user\r\n            INSERT INTO tbl_User (USER_ID, Email_ID, User_Title, User_Role, User_Branch, User_Status,User_Name, Created_By, Created_On)\r\n            VALUES (@USER_ID, @Email_ID, @Title, @Role, @Branch, @Status,@User_Name, @Created_By, @Created_On);\r\n\r\n\t\t\t DECLARE @User_NewId INT = SCOPE_IDENTITY();\r\n\r\n            -- Format the UserId as AGT0001\r\n            DECLARE @User_UserId NVARCHAR(100) = 'USR' + RIGHT('00000' + CAST(@User_NewId AS NVARCHAR), 4);\r\n\t\t\t -- Update the record with the generated UserId\r\n            UPDATE Tbl_User\r\n            SET User_Id = @User_UserId,\r\n\t\t\tCreated_By= @Created_By\r\n            WHERE Id = @User_NewId;\r\n          \r\n        END\r\n        ELSE\r\n        BEGIN\r\n            -- Update existing user\r\n            UPDATE tbl_User\r\n            SET --USER_ID = @USER_ID, \r\n\t\t\t    user_Name = @User_Name,\r\n                Email_ID = @Email_ID, \r\n                User_Title = @Title, \r\n                User_Role = @Role, \r\n                User_Branch = @Branch, \r\n                User_Status = @Status\r\n            WHERE ID = @ID;\r\n        END\r\n           \r\n        END\r\n        ELSE\r\n        BEGIN\r\n            SELECT 'Invalid Action Provided' AS Message;\r\n        END\t\r\n\r\n    END TRY\r\n    BEGIN CATCH\r\n        -- Handle Errors\r\n        SELECT ERROR_MESSAGE() AS ErrorMessage, ERROR_LINE() AS ErrorLine, ERROR_NUMBER() AS ErrorNumber;\r\n    END CATCH\r\nEND;\r\n\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='LoginInsertUser' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[prcDashboard]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='prcDashboard' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prcDashboard]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\nCREATE  PROCEDURE [dbo].[prcDashboard]\r\n\t(\r\n\t\t@RoleID varchar(2),\r\n\t\t@RESULT VARCHAR(1000) OUTPUT\r\n\t)\r\n\tAS\r\n\t\tBEGIN\r\n\r\n\t\t\tIF @RoleID='1' \r\n\t\t\tBEGIN\r\n\t\t\tselect a.[Passport Expire],b.[Contract Expire],c.[Permit Expire] from \r\n\t\t\t\t(select count(passport_Expire_Date) as [Passport Expire] from [dbo].[Tbl_Worker_PersonalInfo]\r\n\t\t\t\twhere passport_Expire_Date <= DATEADD(month, 3, getdate())\r\n\t\t\t\tgroup by passport_Expire_Date) as a, \r\n\r\n\t\t\t\t(select count(contract_Expiry_Date) as [Contract Expire] from [dbo].[Tbl_Worker_EmployerInfo]\r\n\t\t\t\twhere contract_Expiry_Date <= DATEADD(month, 3, getdate())\r\n\t\t\t\tgroup by contract_Expiry_Date) as b,\r\n\r\n\t\t\t\t(select count(Permit_Expire_Date) as [Permit Expire] from [dbo].[Tbl_Worker_PermitInsurance]\r\n\t\t\t\twhere Permit_Expire_Date <= DATEADD(month, 3, getdate())\r\n\t\t\t\tgroup by Permit_Expire_Date) as c\r\n\t\t\tEND\r\n\t\t\r\n\r\n\r\n--exec [prcDashboard] '1',''\r\n\r\n--SELECT * FROM TBL_ROLE\r\n--SELECT  * FROM TBL_USER\r\n\r\n\r\n--\t\t\t\tselect count(passport_Expire_Date) as [Passport Expire] from [dbo].[Tbl_Worker_PersonalInfo]\r\n--\t\t\t\twhere passport_Expire_Date <= DATEADD(month, 3, getdate())\r\n--\t\t\t\tgroup by passport_Expire_Date)\r\n\r\n--\t\t\t\tSELECT * FROM [Tbl_Worker_PersonalInfo]\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='prcDashboard' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_Insert_Tbl_EmployerIndividual]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_Insert_Tbl_EmployerIndividual' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_Insert_Tbl_EmployerIndividual]    Script Date: 9/7/2025 5:45:35 PM ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROCEDURE [dbo].[sp_Insert_Tbl_EmployerIndividual]\r\n    @Action NVARCHAR(50),  -- Determines the action to perform\r\n    @ID INT = NULL, \r\n    @User_Id NVARCHAR(100) = NULL,\r\n    @Employer_Name NVARCHAR(100) = NULL,\r\n\t@Password NVARCHAR(100) =NULL,\r\n    @Employer_Address NVARCHAR(500) = NULL,\r\n    @Employer_ContactPerson NVARCHAR(100) = NULL,\r\n    @Employer_EmailID NVARCHAR(100) = NULL,\r\n    @CountryCode NVARCHAR(10) = NULL,\r\n    @Employer_PIC_MobileNumber NVARCHAR(20) = NULL,\r\n    @Created_By NVARCHAR(100) = NULL,\r\n    @Created_On DATETIME = NULL\r\nAS\r\nBEGIN\r\n    BEGIN TRY\r\n        IF @Action = 'SubmitEmployerIndividual'\r\n        BEGIN\r\n            -- Insert into Tbl_EmployerIndividual\r\n            INSERT INTO Tbl_EmployerIndividual (\r\n                User_Id, Employer_Name, Employer_Address, Employer_ContactPerson, \r\n                Employer_EmailID, CountryCode, Employer_PIC_MobileNumber, Created_By, Created_On\r\n            )\r\n            VALUES (\r\n                @User_Id, @Employer_Name, @Employer_Address, @Employer_ContactPerson, \r\n                @Employer_EmailID, @CountryCode, @Employer_PIC_MobileNumber, @Created_By, GETDATE()\r\n            );\r\n\r\n            -- Retrieve the newly inserted ID\r\n            DECLARE @NewId INT = SCOPE_IDENTITY();\r\n\r\n            -- Generate a formatted User_Id (e.g., EMP0001)\r\n            DECLARE @GeneratedUserId NVARCHAR(100) = 'EMPIND' + RIGHT('00000' + CAST(@NewId AS NVARCHAR), 4);\r\n\r\n            -- Update the record with the generated User_Id\r\n            UPDATE Tbl_EmployerIndividual\r\n            SET User_Id = @GeneratedUserId\r\n            WHERE ID = @NewId;\r\n\r\n\r\n\t\t\t\r\n            -- Insert into Tbl_User for reference\r\n            INSERT INTO Tbl_User (USER_ID, email_id,Login_Pwd, created_by, Created_On, User_Name) \r\n            VALUES (@GeneratedUserId, @Employer_EmailID,@Password, @Created_By, GETDATE(), @Employer_Name);\r\n\r\n            SELECT @GeneratedUserId AS UserId, 'Employer Individual Registered Successfully' AS Message;\r\n        END\r\n        ELSE IF @Action = 'UpdateEmployerIndividual'\r\n        BEGIN\r\n            -- Update existing Employer Individual details\r\n            UPDATE Tbl_EmployerIndividual\r\n            SET Employer_Name = @Employer_Name,\r\n                Employer_Address = @Employer_Address,\r\n                Employer_ContactPerson = @Employer_ContactPerson,\r\n                Employer_EmailID = @Employer_EmailID,\r\n                CountryCode = @CountryCode,\r\n                Employer_PIC_MobileNumber = @Employer_PIC_MobileNumber,\r\n                Created_By = @Created_By,\r\n                Created_On = GETDATE()\r\n            WHERE User_Id = @User_Id;\r\n\r\n            SELECT 'Employer Individual Updated Successfully' AS Message;\r\n        END\r\n        ELSE\r\n        BEGIN\r\n            SELECT 'Invalid Action Provided' AS Message;\r\n        END\r\n    END TRY\r\n    BEGIN CATCH\r\n        -- Handle Errors\r\n        SELECT ERROR_MESSAGE() AS ErrorMessage, ERROR_LINE() AS ErrorLine, ERROR_NUMBER() AS ErrorNumber;\r\n    END CATCH\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']/StoredProcedure[@Name='sp_Insert_Tbl_EmployerIndividual' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [ADS_FWWMC_DB]"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["USE [master]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER DATABASE [ADS_FWWMC_DB] SET  READ_WRITE \r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='P3NWPLSKSQL20']/Database[@Name='ADS_FWWMC_DB']","object_type":"Database"}}]}
